const width = 30;
final words = paragraph.split(' ');
var start = 0;
while (start < words.length) {
  var end = start, letters = 0;
  while (end < words.length &&
      letters + words[end].length + (end - start) <= width) {
    letters += words[end].length;
    end++;
  final n = end - start;
  out.write('|');
  if (end == words.length || n == 1) {
    final line = words.sublist(start, end).join(' ');
    out.write(line.padRight(width));
  } else {
    final spaces = width - letters, gaps = n - 1;
    for (var i = 0; i < n; i++) {
      out.write(words[start + i]);
      if (i < gaps) {
        out.write(' ' * (spaces ~/ gaps + (i < spaces % gaps ? 1 : 0)));
  out.writeln('|');
  start = end;
stdout.write(out);
